//상세페이지
function fnMoveDtlPage(recrOpeningId, rnum) {
	$("#frm #srchRecrOpeningId").val(recrOpeningId);	
	cf_SearchAjax("frm", "/recruit/rj00/jsonRn00RN10110.do", function(data){
		if(data.success){
			$("#frm #pageIndex").val('1');
			$("#frm #srchRecrOpeningId").val(recrOpeningId);	
			$("#frm #rnum").val(rnum);	
